package com.aoo.bcg.common.transaction;
import java.sql.Connection;import java.util.Objects;import javax.sql.DataSource;
/** Consistent JDBC boundary: every rejection or checked/unchecked failure rolls back before propagation. */
public final class JdbcTransactionBoundary{private final DataSource dataSource;public JdbcTransactionBoundary(DataSource dataSource){this.dataSource=Objects.requireNonNull(dataSource);}public <T>T execute(Work<T>work)throws Exception{Objects.requireNonNull(work);try(Connection connection=dataSource.getConnection()){boolean original=connection.getAutoCommit();connection.setAutoCommit(false);try{T result=work.run(connection);connection.commit();return result;}catch(Throwable failure){try{connection.rollback();}catch(Throwable rollbackFailure){failure.addSuppressed(rollbackFailure);}if(failure instanceof Exception exception)throw exception;if(failure instanceof Error error)throw error;throw new IllegalStateException(failure);}finally{connection.setAutoCommit(original);}}}@FunctionalInterface public interface Work<T>{T run(Connection connection)throws Exception;}}
